param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$marvin=[object].Assembly.GetType('System.Marvin',$true);$flags=[Reflection.BindingFlags]'Static,Public,NonPublic';$method=$marvin.GetMethods($flags)|Where-Object {$_.Name -eq 'ComputeHash32' -and $_.GetParameters().Count -eq 4 -and $_.GetParameters()[0].ParameterType.IsByRef};if(@($method).Count -ne 1){throw 'Pinned Marvin method identity mismatch'}
$dynamic=[Reflection.Emit.DynamicMethod]::new('PinnedMarvinByteArray',[int],[type[]]@([byte[]],[int],[uint32],[uint32]),[object].Module,$true);$il=$dynamic.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[byte]);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Conv_U4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Call,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret)
$definition=[type]'System.Func`5';$delegateType=$definition.MakeGenericType([type[]]@([byte[]],[int],[uint32],[uint32],[int]));$hash=$dynamic.CreateDelegate($delegateType)
$seeds=@(@(0L,0L),@(4294967295L,0L),@(0L,4294967295L),@(4294967295L,4294967295L),@(19088743L,2309737967L),@(2147483648L,2147483647L))
$inputs=[Collections.Generic.List[byte[]]]::new();[uint32]$state=123456789
foreach($length in 0..128){$data=[byte[]]::new($length);for($i=0;$i -lt $length;$i++){$state=[uint32](([uint64]$state*1664525+1013904223)-band 4294967295L);$data[$i]=[byte]($state -shr 24)};$inputs.Add($data)}
foreach($length in 1..16){$inputs.Add([byte[]]::new($length));$data=[byte[]]::new($length);for($i=0;$i -lt $length;$i++){$data[$i]=255};$inputs.Add($data)}
$vectors=@();foreach($data in $inputs){$padded=[byte[]]::new($data.Length+4);[Array]::Copy($data,$padded,$data.Length);foreach($seed in $seeds){$value=$hash.Invoke($padded,$data.Length,[uint32]$seed[0],[uint32]$seed[1]);$vectors+=[ordered]@{bytes=[int[]]$data;seed0=$seed[0];seed1=$seed[1];hash=$value}}}
$strings=@(@(),@(0),@(63),@(65),@(65,66),@(0xfffd),@(0xd800),@(0xdc00),@(0xd800,0xdc00),@(0xdbff,0xdfff),@(65,0,66),@(0xffff,0,0x800),@(0x7f,0x80,0x7ff,0x800))
foreach($value in 0..255){$strings+=,@($value)}
$defaultSeedProperty=$marvin.GetProperty('DefaultSeed',$flags);$defaultSeed=[uint64]$defaultSeedProperty.GetValue($null);$stringRows=@()
foreach($units in $strings){$chars=[char[]][int[]]$units;$text=[string]::new($chars);$raw=[byte[]]::new($chars.Length*2);[Buffer]::BlockCopy($chars,0,$raw,0,$raw.Length);$padded=[byte[]]::new($raw.Length+4);[Array]::Copy($raw,$padded,$raw.Length);$controlled=@(foreach($seed in $seeds){[ordered]@{seed0=$seed[0];seed1=$seed[1];hash=$hash.Invoke($padded,$raw.Length,[uint32]$seed[0],[uint32]$seed[1])}});$nativeHash=$text.GetHashCode();$linked=($hash.Invoke($padded,$raw.Length,[uint32]($defaultSeed -band 4294967295L),[uint32]($defaultSeed -shr 32)) -eq $nativeHash)
 try{$encoder=[Text.EncoderReplacementFallback]::new($text);$decoder=[Text.DecoderReplacementFallback]::new($text);$fallback=[ordered]@{supported=$true;encoderHash=$encoder.GetHashCode();decoderHash=$decoder.GetHashCode();sameAsString=($encoder.GetHashCode() -eq $nativeHash -and $decoder.GetHashCode() -eq $nativeHash);stable=($encoder.GetHashCode() -eq $encoder.GetHashCode());equalObjectHash=($encoder.GetHashCode() -eq ([Text.EncoderReplacementFallback]::new($text)).GetHashCode())}}catch{$fallback=[ordered]@{supported=$false}}
 $stringRows+=[ordered]@{units=[int[]]$units;nativeProcessLocalHash=$nativeHash;linkedToPinnedMarvin=$linked;controlled=$controlled;fallback=$fallback}
}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();nativeMethod=$method.ToString();littleEndian=[BitConverter]::IsLittleEndian;controlledVectors=$vectors;stringRows=$stringRows;encoderExceptionHash=([Text.EncoderExceptionFallback]::new()).GetHashCode();decoderExceptionHash=([Text.DecoderExceptionFallback]::new()).GetHashCode();nativeDefaultSeedSerialized=$false;qualification='CONTROLLED_PINNED_MARVIN_AND_PROCESS_LOCAL_HASH_CONTRACT_ONLY; RAW_CROSS_PROCESS_HASH_EQUALITY_FULL_OBJECT_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned fallback hashing: $($vectors.Count) byte vectors and $($stringRows.Count) UTF-16 strings with six controlled seeds"
